#### 2.1 Frame Reference Counting (for COW)

Add to frame allocator or new section:

```rust
/// Per-frame metadata for reference counting
pub struct FrameInfo {
    /// Number of page table entries pointing to this frame
    refcount: AtomicU32,
    /// Frame state
    state: FrameState,
}

pub enum FrameState {
    Free,
    Allocated,
    Reserved,  // Kernel, MMIO, etc.
}

impl FrameAllocator {
    /// Increment reference count (used during fork COW setup)
    pub fn inc_refcount(&self, frame: PhysAddr) {
        let info = self.frame_info(frame);
        info.refcount.fetch_add(1, Ordering::Relaxed);
    }

    /// Decrement reference count, free if zero
    pub fn dec_refcount(&self, frame: PhysAddr) -> bool {
        let info = self.frame_info(frame);
        let old = info.refcount.fetch_sub(1, Ordering::Release);
        if old == 1 {
            // Last reference - actually free the frame
            self.free_frame(frame);
            true
        } else {
            false
        }
    }

    /// Check if frame is shared (refcount > 1)
    pub fn is_shared(&self, frame: PhysAddr) -> bool {
        self.frame_info(frame).refcount.load(Ordering::Relaxed) > 1
    }
}
```

Update COW handler to use refcount:

```rust
fn handle_cow(memory: &mut ProcessMemory, addr: VirtAddr) -> PageFaultResult {
    let page = VirtAddr::new(addr.as_u64() & !0xFFF);
    let old_frame = memory.address_space.translate(page).unwrap();

    // Check if we actually need to copy
    if !FRAME_ALLOCATOR.lock().is_shared(old_frame) {
        // We're the only owner - just make it writable
        memory.address_space.update_flags(page, |flags| {
            flags.remove(PageTableFlags::COPY_ON_WRITE);
            flags.insert(PageTableFlags::WRITABLE);
        });
        return PageFaultResult::CopyOnWrite;
    }

    // Frame is shared - must copy
    let new_frame = FRAME_ALLOCATOR.lock().allocate_frame()
        .map_err(|_| return PageFaultResult::OutOfMemory)?;

    // Copy page contents
    unsafe {
        let src = kernel_virt::phys_to_virt(old_frame).as_ptr::<u8>();
        let dst = kernel_virt::phys_to_virt(new_frame).as_mut_ptr::<u8>();
        core::ptr::copy_nonoverlapping(src, dst, PAGE_SIZE);
    }

    // Decrement old frame refcount
    FRAME_ALLOCATOR.lock().dec_refcount(old_frame);

    // Map new frame as writable
    memory.address_space.remap(page, new_frame,
        PageTableFlags::PRESENT | PageTableFlags::WRITABLE | PageTableFlags::USER);

    // Invalidate TLB for this page
    unsafe { asm!("invlpg [{}]", in(reg) page.as_u64()); }

    PageFaultResult::CopyOnWrite
}
```

#### 2.2 OOM Handling

Add `OutOfMemory` to PageFaultResult:

