**Location**: After exception handlers, new section "Exception Tables"

Add section: "Exception Tables for Safe Kernel Faults"

```rust
/// Exception table entry: maps faulting instruction to recovery address
#[repr(C)]
pub struct ExceptionTableEntry {
    /// Address of instruction that might fault
    insn: u64,
    /// Address to jump to if fault occurs
    fixup: u64,
}

/// Linker-provided exception table boundaries
extern "C" {
    static __start_exception_table: ExceptionTableEntry;
    static __stop_exception_table: ExceptionTableEntry;
}

/// Look up fixup address for a faulting instruction
pub fn lookup_fixup(fault_rip: u64) -> Option<u64> {
    let start = &__start_exception_table as *const _ as usize;
    let stop = &__stop_exception_table as *const _ as usize;
    let entries = (stop - start) / core::mem::size_of::<ExceptionTableEntry>();

    let table = unsafe {
        core::slice::from_raw_parts(&__start_exception_table, entries)
    };

    // Binary search (table is sorted by linker)
    table.binary_search_by_key(&fault_rip, |e| e.insn)
        .ok()
        .map(|i| table[i].fixup)
}

/// Macro for safe user memory access
#[macro_export]
macro_rules! copy_from_user {
    ($dst:expr, $src:expr, $len:expr) => {{
        let result: Result<(), Errno>;
        unsafe {
            asm!(
                "1: rep movsb",
                "2:",
                ".pushsection .exception_table, \"a\"",
                ".quad 1b, 3f",
                ".popsection",
                "jmp 4f",
                "3: mov {0}, {1}",
                "4:",
                out(reg) result,
                const Errno::EFAULT as i64,
                inout("rdi") $dst => _,
                inout("rsi") $src => _,
                inout("rcx") $len => _,
            );
        }
        result
    }}
}
```

