# Shebang Script Support + Positional Parameters for Jake

## Overview
Two related features:
1. **Shebang scripts**: Recipes starting with `#!/...` are treated as polyglot scripts
2. **Positional parameters**: `jake say "Hello"` binds to first param instead of requiring `text="Hello"`

## Example Usage

**Shebang scripts:**
```jake
task watch:
    #!/usr/bin/env node
    const fs = require('fs');
    console.log('Hello from Node.js!');
```

**Positional parameters:**
```bash
# Before (required):
jake say text="Hello human"

# After (also works):
jake say "Hello human"
```

**How shebang execution works:**
When executed, Jake will:
1. Collect all lines into a single script
2. Write to a temp file
3. Make executable and run with the shebang interpreter
4. Clean up the temp file

---

## Implementation Approach

### Key Decision: Parser-level detection, Executor-level execution

- **Lexer**: No changes needed (shebang lines tokenize as comments, which is fine)
- **Parser**: Detect shebang, store script body in Recipe struct
- **Executor**: Execute shebang scripts via temp file

---

## File Changes

### 1. `src/parser.zig` - Recipe Struct Update

**Add new fields to Recipe struct (around line 27):**
```zig
script_body: ?[]const u8 = null,    // Full script content (for shebang recipes)
script_shebang: ?[]const u8 = null, // Interpreter line e.g. "#!/usr/bin/env node"
```

**Add post-processing after command collection in `parseTaskRecipe()`, `parseSimpleRecipe()`, `parseFileRecipe()`:**

After `commands` ArrayList is populated but before creating the Recipe:
```zig
// Check for shebang script
var script_body: ?[]const u8 = null;
var script_shebang: ?[]const u8 = null;

if (commands.items.len > 0) {
    const first_line = std.mem.trimLeft(u8, commands.items[0].line, " \t");
    if (std.mem.startsWith(u8, first_line, "#!")) {
        // This is a shebang script - join all commands
        script_shebang = first_line;

        var script = std.ArrayList(u8).init(self.allocator);
        for (commands.items) |cmd| {
            try script.appendSlice(cmd.line);
            try script.append('\n');
        }
        script_body = try script.toOwnedSlice();

        // Clear commands - they're now in script_body
        commands.clearRetainingCapacity();
    }
}
```

### 2. `src/executor.zig` - Script Execution

**Add temp file tracking to Executor struct (around line 39):**
```zig
temp_scripts: std.ArrayListUnmanaged([]const u8) = .empty,
```

**Add cleanup in `deinit()` (around line 618):**
```zig
// Clean up temp script files
for (self.temp_scripts.items) |path| {
    std.fs.cwd().deleteFile(path) catch {};
    self.allocator.free(path);
}
self.temp_scripts.deinit(self.allocator);
```

**Add new function `executeShebangScript()`:**
```zig
fn executeShebangScript(self: *Executor, recipe: *const Recipe) ExecuteError!void {
    const script_body = recipe.script_body orelse return;
    const shebang = recipe.script_shebang orelse return;

    // 1. Expand Jake variables in script
    const expanded = self.expandJakeVariables(script_body) catch script_body;

    // 2. Create temp file
    const timestamp = std.time.nanoTimestamp();
    var path_buf: [256]u8 = undefined;
    const tmp_path = std.fmt.bufPrint(&path_buf, "/tmp/jake_script_{d}", .{timestamp})
        catch return ExecuteError.CommandFailed;

    const file = std.fs.cwd().createFile(tmp_path, .{ .mode = 0o755 })
        catch return ExecuteError.CommandFailed;
    file.writeAll(expanded) catch {
        file.close();
        return ExecuteError.CommandFailed;
    };
    file.close();

    // Track for cleanup
    const path_copy = self.allocator.dupe(u8, tmp_path) catch return ExecuteError.OutOfMemory;
    self.temp_scripts.append(self.allocator, path_copy) catch return ExecuteError.OutOfMemory;

    // 3. Execute the script directly (shebang handles interpreter)
    var child = std.process.Child.init(&[_][]const u8{path_copy}, self.allocator);
    child.stderr_behavior = .Inherit;
    child.stdout_behavior = .Inherit;

    if (self.current_working_dir) |wd| child.cwd = wd;

    var env_map = self.environment.buildEnvMap(self.allocator) catch {
        return ExecuteError.CommandFailed;
    };
    defer env_map.deinit();
    child.env_map = &env_map;

    _ = child.spawn() catch return ExecuteError.CommandFailed;
    const result = child.wait() catch return ExecuteError.CommandFailed;

    // 4. Check result
    switch (result) {
        .Exited => |code| if (code != 0) return ExecuteError.CommandFailed,
        else => return ExecuteError.CommandFailed,
    }
}
```

**Modify `executeRecipeInternal()` (around line 756):**
