## Feature 2: Positional Parameter Binding

### `src/executor.zig` - Modify `bindRecipeParams()` (around line 805)

**Current code (only binds `key=value` args):**
```zig
fn bindRecipeParams(self: *Executor, recipe: *const Recipe) !void {
    var cli_args = std.StringHashMap([]const u8).init(self.allocator);
    defer cli_args.deinit();

    for (self.positional_args) |arg| {
        if (std.mem.indexOfScalar(u8, arg, '=')) |eq_pos| {
            const key = arg[0..eq_pos];
            const value = arg[eq_pos + 1 ..];
            try cli_args.put(key, value);
        }
    }
    // ... bind to recipe params
}
```

**New code (also binds positional args to params in order):**
```zig
fn bindRecipeParams(self: *Executor, recipe: *const Recipe) !void {
    var cli_args = std.StringHashMap([]const u8).init(self.allocator);
    defer cli_args.deinit();

    // Track positional args without '=' for ordered binding
    var positional_values: std.ArrayListUnmanaged([]const u8) = .empty;
    defer positional_values.deinit(self.allocator);

    for (self.positional_args) |arg| {
        if (std.mem.indexOfScalar(u8, arg, '=')) |eq_pos| {
            // Named arg: key=value
            const key = arg[0..eq_pos];
            const value = arg[eq_pos + 1 ..];
            try cli_args.put(key, value);
        } else {
            // Positional arg: add to list for ordered binding
            try positional_values.append(self.allocator, arg);
        }
    }

    // Bind recipe parameters
    var positional_idx: usize = 0;
    for (recipe.params) |param| {
        if (cli_args.get(param.name)) |value| {
            // Named arg takes precedence
            try self.variables.put(param.name, value);
        } else if (positional_idx < positional_values.items.len) {
            // Bind next positional arg
            try self.variables.put(param.name, positional_values.items[positional_idx]);
            positional_idx += 1;
        } else if (param.default) |default_value| {
            // Use default value
            try self.variables.put(param.name, default_value);
        }
        // If no CLI arg, no positional, and no default, param is not set
    }
}
```

