pub fn resolveAllImports(self: *ImportResolver, ...) !Jakefile {
    // ... existing Jake import resolution

    // NEW: Also load external files if present
    const external_files = external.detectExternalFiles(self.base_dir);

    if (external_files.makefile) |mf| {
        const make_recipes = try external.parseMakefile(self.allocator, mf);
        try self.mergeRecipes(target, make_recipes);
    }

    if (external_files.justfile) |jf| {
