```zig
pub fn listRecipes(self: *Executor, short_mode: bool, show_all: bool) void {
    // Categorize recipes by origin
    var jake_recipes = ArrayList(*const Recipe).init(self.allocator);
    var make_recipes = ArrayList(*const Recipe).init(self.allocator);
    var just_recipes = ArrayList(*const Recipe).init(self.allocator);

    for (self.jakefile.recipes) |*recipe| {
        if (recipe.origin) |origin| {
            if (origin.external_kind) |kind| {
                switch (kind) {
                    .makefile => make_recipes.append(recipe),
                    .justfile => just_recipes.append(recipe),
                }
                continue;
            }
        }
        jake_recipes.append(recipe);
    }

    // Display Jake recipes (existing logic)
    // ...

    // Display external sections with different colors
    if (make_recipes.items.len > 0) {
        self.printExternalSection("make", make_recipes.items);
    }
    if (just_recipes.items.len > 0) {
        self.printExternalSection("just", just_recipes.items);
    }
}
```

### Step 5: Handle external execution in `src/executor.zig`

When executing a recipe with `origin.external_kind != null`, delegate to the external tool:

```zig
fn executeRecipeCommands(self: *Executor, recipe: *const Recipe) !void {
    // Check if this is an external recipe
    if (recipe.origin) |origin| {
        if (origin.external_kind) |kind| {
            return self.executeExternalRecipe(origin, kind);
        }
    }

    // ... existing Jake execution logic
}

fn executeExternalRecipe(self: *Executor, origin: RecipeOrigin, kind: ExternalKind) !void {
    const tool = switch (kind) { .makefile => "make", .justfile => "just" };
    const flag = switch (kind) { .makefile => "-f", .justfile => "--justfile" };

    var child = std.process.Child.init(
        &.{ tool, flag, origin.source_file.?, origin.original_name },
        self.allocator,
    );
    child.stdout_behavior = .Inherit;
    child.stderr_behavior = .Inherit;
    _ = try child.spawnAndWait();
}
```

