fn mouseButtonCallback(window, button, action, mods) {
    if (action != .press) return;

    const self = window.getUserPointer(Window);
    const tab_manager = self.tab_manager orelse return;

    // Check if click is in tab bar (y < cell_height)
    if (self.last_mouse_y < self.cell_height) {
        if (button == .left) {
            // Left click: switch tab or create new
            if (hitTestTab(self.last_mouse_x)) |tab_index| {
                // Double-click check for rename
                const now = glfw.getTime();
                if (now - self.last_click_time < 0.3 and
                    @abs(self.last_mouse_x - self.last_click_x) < 5) {
                    enterRenameMode(tab_index);
                } else {
                    tab_manager.switchTab(tab_index);
                }
                self.last_click_time = now;
                self.last_click_x = self.last_mouse_x;
            } else if (hitTestNewButton(self.last_mouse_x)) {
                tab_manager.createTab("Shell");
            }
        } else if (button == .right) {
            // Right click: show color menu
            if (hitTestTab(self.last_mouse_x)) |tab_index| {
                showColorMenu(tab_index);
            }
        }
    }
}
