/// slack(channel, message, webhook?)
pub fn slack(
    allocator: std.mem.Allocator,
    args: MultiArgs,
    variables: *const StringHashMap,
    env: *const Environment,
) ![]const u8 {
    const channel = args.positional[0];
    const message = args.positional[1];
    const webhook = args.getNamed("webhook") orelse
                    variables.get("slack_webhook") orelse
                    env.get("JAKE_SLACK_WEBHOOK") orelse
                    return NotificationError.MissingWebhook;

    const payload = try formatSlackPayload(allocator, channel, message);
    defer allocator.free(payload);

    var client = HttpClient.init(allocator);
    const response = try client.post(webhook, payload, "application/json");

    return if (response.status == 200) "ok" else "failed";
}

