pub fn gitHash(allocator: std.mem.Allocator, args: MultiArgs) ![]const u8 {
    const short = args.getBool("short") orelse false;
    const fallback = args.getNamed("fallback") orelse "";

    const format = if (short) "%h" else "%H";
    const result = try runGitCommand(allocator, &.{"log", "-1", "--format=" ++ format});
    return if (result.len > 0) result else allocator.dupe(u8, fallback);
