pub fn evaluate(allocator: std.mem.Allocator, call: []const u8, variables: *const StringHashMap, env: ?*const Environment) FunctionError![]const u8 {
    const paren_start = std.mem.indexOfScalar(u8, call, '(') orelse return FunctionError.InvalidArguments;
