### Step 3: Add Auto-Open Logic

**File**: `crates/markdown_preview/src/markdown_preview.rs`

Modify `init` function to subscribe to workspace events:
```rust
pub fn init(cx: &mut App) {
    cx.observe_new(|workspace: &mut Workspace, window, cx| {
        let Some(window) = window else { return; };
        markdown_preview_view::MarkdownPreviewView::register(workspace, window, cx);

        // Subscribe to workspace events for auto-open functionality
        cx.subscribe(workspace, move |workspace, event, cx| {
            if let workspace::Event::ActiveItemChanged = event {
                if let Some(window) = cx.window_handle().and_then(|h| h.downcast()) {
                    window.update(cx, |_, window, cx| {
                        markdown_preview_view::MarkdownPreviewView::maybe_auto_open_preview(
                            workspace, window, cx
                        );
                    }).ok();
                }
            }
        }).detach();
    }).detach();
}
```

**File**: `crates/markdown_preview/src/markdown_preview_view.rs`

Add new method after `register()` (~line 128):
```rust
/// Auto-opens following markdown preview to the side if:
/// 1. Setting is enabled for Markdown language
/// 2. Active item is a markdown editor
/// 3. No following preview exists anywhere in workspace
pub fn maybe_auto_open_preview(
    workspace: &mut Workspace,
    window: &mut Window,
    cx: &mut Context<Workspace>,
) {
    // Check if active item is markdown editor
    let Some(editor) = Self::resolve_active_item_as_markdown_editor(workspace, cx) else {
        return;
    };

    // Check language setting
    let settings = language::language_settings::language_settings(
        Some(LanguageName::new("Markdown")),
        editor.read(cx).file(0, cx).as_ref(),
        cx,
    );

    if !settings.auto_open_preview {
        return;
    }

    // Check if following preview already exists
    let following_preview_exists = workspace.panes().iter().any(|pane| {
        pane.read(cx)
            .items_of_type::<MarkdownPreviewView>()
            .any(|view| view.read(cx).mode == MarkdownPreviewMode::Follow)
    });

    if following_preview_exists {
        return;
    }

    // Open following preview to the side
    let view = Self::create_following_markdown_view(workspace, editor.clone(), window, cx);
    let pane = workspace
        .find_pane_in_direction(workspace::SplitDirection::Right, cx)
        .unwrap_or_else(|| {
            workspace.split_pane(
                workspace.active_pane().clone(),
                workspace::SplitDirection::Right,
                window,
                cx,
            )
        });

    pane.update(cx, |pane, cx| {
        pane.add_item(Box::new(view), false, false, None, window, cx);
    });

    editor.focus_handle(cx).focus(window, cx);
    cx.notify();
}
```

Add import at top:
```rust
