pub const Zone = if (enabled)
    ztracy.ZoneCtx
else
    struct {
        pub inline fn End(self: @This()) void { _ = self; }
    };

/// Create a named zone for profiling
pub inline fn zone(comptime name: [:0]const u8) Zone {
    if (enabled) {
        return ztracy.ZoneNC(@src(), name, 0x00_ff_00_00);
    }
    return .{};
}

/// Create a zone with custom color
pub inline fn zoneC(comptime name: [:0]const u8, color: u32) Zone {
    if (enabled) {
        return ztracy.ZoneNC(@src(), name, color);
    }
    return .{};
}
