const bench_parallel = @import("bench_parallel.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();

    var bench = zbench.Benchmark.init(gpa.allocator(), .{});
    defer bench.deinit();

