    bench_lexer.register(&bench);
    bench_executor.register(&bench);
    bench_glob.register(&bench);
    bench_cache.register(&bench);
    bench_parallel.register(&bench);

    // Run and output
    try bench.run(std.io.getStdOut().writer());
}
