pub fn printError(writer: anytype, err: ParseError, arg: []const u8, context: ?ErrorContext) void {
    switch (err) {
        error.UnknownFlag => { /* existing logic */ },
        error.MissingValue => {
            writer.print(ansi.err_prefix ++ "Option '{s}' requires a value\n", .{arg}) catch {};
            if (context) |ctx| {
                if (ctx.value_name) |name| {
                    writer.print("       Expected: {s}\n", .{name}) catch {};
                }
            }
            writer.writeAll("Usage: jake [options] [recipe] [args...]\n") catch {};
        },
        error.InvalidValue => {
            writer.print(ansi.err_prefix ++ "Invalid value for '{s}': {s}\n", .{arg, context.?.provided_value orelse "?"}) catch {};
            if (context) |ctx| {
                if (ctx.choices) |choices| {
                    writer.writeAll("       Valid options: ") catch {};
                    // Print choices
                }
            }
        },
        error.InvalidChoice => {
            // New error type for enum restrictions
        },
    }
}
```

