**New listGroups function**:
```zig
pub fn listGroups(self: *Executor) void {
    var groups = std.StringHashMap(usize).init(self.allocator);
    defer groups.deinit();

    for (self.jakefile.recipes) |*recipe| {
        if (recipe.group) |group| {
            const entry = groups.getOrPut(group) catch continue;
            if (!entry.found_existing) entry.value_ptr.* = 0;
            entry.value_ptr.* += 1;
        }
    }

    // Print: "group-name (N recipes)"
    const stdout = compat.getStdOut();
    var iter = groups.iterator();
    while (iter.next()) |entry| {
        stdout.print("{s} ({d} recipes)\n", .{entry.key_ptr.*, entry.value_ptr.*}) catch {};
    }
}
