### 3.2 JSON Helper Module (new file: src/json_output.zig)

```zig
const std = @import("std");
const parser = @import("parser.zig");

pub fn writeRecipeJson(writer: anytype, recipe: *const parser.Recipe) !void {
    try writer.writeAll("{");
    try writer.print("\"name\":\"{s}\"", .{escapeJson(recipe.name)});
    try writer.print(",\"type\":\"{s}\"", .{@tagName(recipe.kind)});
    if (recipe.description) |desc| {
        try writer.print(",\"description\":\"{s}\"", .{escapeJson(desc)});
    }
    if (recipe.group) |group| {
        try writer.print(",\"group\":\"{s}\"", .{escapeJson(group)});
    }
    try writer.print(",\"default\":{}", .{recipe.is_default});
    // ... dependencies, params, aliases ...
    try writer.writeAll("}");
}

pub fn writeRecipesListJson(writer: anytype, recipes: []const *const parser.Recipe, groups: []const []const u8) !void {
    try writer.writeAll("{\"recipes\":[");
    for (recipes, 0..) |recipe, i| {
        if (i > 0) try writer.writeAll(",");
        try writeRecipeJson(writer, recipe);
    }
    try writer.print("],\"count\":{d},\"groups\":[", .{recipes.len});
    for (groups, 0..) |group, i| {
        if (i > 0) try writer.writeAll(",");
        try writer.print("\"{s}\"", .{escapeJson(group)});
    }
    try writer.writeAll("]}");
}

fn escapeJson(s: []const u8) []const u8 {
    // Escape special chars: ", \, newlines, etc.
    // For simplicity, can use std.json.encodeJsonString
}
